package glitch

import data.glitch_lib

password_keywords := {
    "password",
    "pass",
    "pwd",
    "secret",
    "token",
    "key"
}

is_password_related(name) {
    password_keywords[name]
} else {
    lower_name := lower(name)
    contains(lower_name, "password")
} else {
    lower_name := lower(name)
    contains(lower_name, "secret")
} else {
    lower_name := lower(name)
    contains(lower_name, "_key")
} else {
    lower_name := lower(name)
    contains(lower_name, "_token")
}

contains(str, substr) {
    regex.match(sprintf(".*%s.*", [substr]), str)
}

lower(s) = lower_s {
    lower_s := regex.replace(s, "[A-Z]", {c | char := c; ascii := to_number(char[c]); ascii >= 65; ascii <= 90; lower_ascii := ascii + 32; sprintf("%c", [lower_ascii])})
} else = s {
    true
}

to_number(c) = n {
    n := c[0]
}

is_literal_string(val) {
    val.ir_type == "String"
    val.value != ""
    not starts_with_expression(val.value)
}

starts_with_expression(value) {
    regex.match("^\\$\\{", value)
} else {
    regex.match("^%\\{", value)
}

contains_password_in_string(str) {
    lower_str := lower(str)
    contains(lower_str, "password=")
} else {
    lower_str := lower(str)
    contains(lower_str, "passwd=")
} else {
    lower_str := lower(str)
    contains(lower_str, "pwd=")
} else {
    lower_str := lower(str)
    contains(lower_str, "secret=")
}

analyze_value(val, path, result) = r {
    # Case 1: Direct string value with password-related field
    val.ir_type == "String"
    is_literal_string(val)
    r := [{
        "detected": true,
        "element": val,
        "reason": "literal password string"
    }]
} else = r {
    # Case 2: Check string for embedded credentials (e.g., connection strings, env vars)
    val.ir_type == "String"
    val.value != ""
    contains_password_in_string(val.value)
    r := [{
        "detected": true,
        "element": val,
        "reason": "embedded credential in string"
    }]
} else = r {
    # Case 3: Hash containing password-related keys
    val.ir_type == "Hash"
    r := [detection |
        [key_expr, value_expr] := val.value[_]
        key_name := get_key_name(key_expr)
        is_password_related(key_name)
        nested := analyze_value(value_expr, array.concat(path, [key_name]), result)
        detection := nested[_]
    ]
} else = r {
    # Case 4: Array containing potential passwords
    val.ir_type == "Array"
    r := [detection |
        idx := [i | i := range(count(val.value))][_]
        elem := val.value[idx]
        elem.ir_type == "String"
        # Check for env var format like KEY=value
        contains(elem.value, "=")
        parts := split(elem.value, "=")
        count(parts) >= 2
        key_name := parts[0]
        is_password_related(key_name)
        is_literal_string(elem)
        detection := {
            "detected": true,
            "element": elem,
            "reason": "array element with credential"
        }
    ]
    count(r) > 0
} else = [] {
    true
}

get_key_name(key_expr) = name {
    key_expr.ir_type == "String"
    name := key_expr.value
} else = name {
    key_expr.ir_type == "VariableReference"
    name := key_expr.value
} else = "" {
    true
}

get_first_part(str) = part {
    parts := split(str, "=")
    count(parts) > 0
    part := parts[0]
}

